import { headers } from 'next/headers';

interface PageViewData {
  path: string;
  userAgent: string | null;
  timestamp: string;
  referrer: string | null;
}

/**
 * Simulated analytics service that logs page views.
 * In production, this would call an external analytics API.
 */
export async function logPageView(data: PageViewData): Promise<void> {
  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, 100));

  // Log to console (in production, this would send to your analytics service)
  console.log('[Analytics] Page view logged:', {
    ...data,
    timestamp: new Date().toISOString()
  });
}

/**
 * Logs page view analytics without blocking the response.
 * Uses fire-and-forget pattern to ensure the response isn't delayed.
 */
export async function trackPageView(): Promise<void> {
  const headersList = await headers();

  const pageViewData: PageViewData = {
    path: headersList.get('x-invoke-path') || '/',
    userAgent: headersList.get('user-agent'),
    timestamp: new Date().toISOString(),
    referrer: headersList.get('referer'),
  };

  // Fire-and-forget: Don't await the analytics call
  // This ensures the response isn't blocked by analytics logging
  logPageView(pageViewData).catch(error => {
    console.error('[Analytics] Failed to log page view:', error);
  });
}

